ANALYSIS:
- The rule accesses Tekton pipeline task references through `tekton.untagged_task_references()` and `lib.tasks_from_pipelinerun()` to identify tasks without proper tag references
- The rule iterates over untagged task references in Tekton pipelines, extracting task information including the task name and reference details using the `_task_info` helper function
- The core validation logic triggers a violation when any Tekton task reference lacks a tagged value, specifically checking for untagged references in the bundle format
- The result is generated using `lib.result_helper_with_term()` which creates a warning message containing the pipeline task name and formatted task reference information for reporting

RULE:
```rego
package trusted_task

import rego.v1
import data.lib
import data.lib.image
import data.lib.tekton

_task_info(task) := info if {
	ref := tekton.task_ref(task)
	info := sprintf("%s@%s", [object.get(ref, "key", ""), object.get(ref, "pinned_ref", "")])
}

# METADATA
# title: Task references are tagged
# description: >-
#   Check if all Tekton Tasks defined with the bundle format contain a tag reference.
# custom:
#   short_name: tagged
#   failure_msg: Pipeline task %q uses an untagged task reference, %s
#   solution: >-
#     Update the Pipeline definition so that all Task references have a tagged value as mentioned
#     in the description.
#   collections:
#   - redhat
#   - redhat_rpms
#   effective_on: 2024-05-07T00:00:00Z
#
warn contains result if {
	some task in tekton.untagged_task_references(lib.tasks_from_pipelinerun)
	result := lib.result_helper_with_term(
		rego.metadata.chain(),
		[tekton.pipeline_task_name(task), _task_info(task)],
		tekton.task_name(task),
	)
}
