ANALYSIS:
- The rule accesses rule data named `allowed_rpm_signature_keys` via `lib.rule_data()` to validate the format of RPM signature keys.
- It iterates over the keys in `allowed_rpm_signature_keys` and checks if each key is either "unsigned" or matches a 16-character hexadecimal regex pattern.
- A violation is triggered if any key does not conform to the expected format, resulting in an error message with severity "failure".
- The result is generated as a deny rule output using `lib.result_helper_with_severity()` that includes the error message and severity.

RULE:
```rego
package rpm_signature

import rego.v1
import data.lib
import data.lib.json as j

_allowed_rpm_signature_keys := lib.rule_data("allowed_rpm_signature_keys")

_is_valid_key(key) if {
	# "unsigned" is a special value that indicates no signatures.
	key == "unsigned"
} else if {
	# Rego's JSON Schema processor doesn't seem to handle "pattern". So we do it "manually" here :(
	regex.match(`[a-fA-F0-9]{16}`, key)
}

_rpms_data_result_name := "RPMS_DATA"


_rule_data_errors contains error if {
	some key in _allowed_rpm_signature_keys
	not _is_valid_key(key)
	error := {
		"message": sprintf("Unexpected format of signing key %q", [key]),
		"severity": "failure",
	}
}

# METADATA
# title: Rule data provided
# description: >-
#   Confirm the expected `allowed_rpm_signature_keys` rule data key has been provided in the
#   expected format.
# custom:
#   short_name: rule_data_provided
#   failure_msg: '%s'
#   collections:
#   - redhat
#   - redhat_rpms
#   - policy_data
#   effective_on: 2024-10-05T00:00:00Z
#
deny contains result if {
	some e in _rule_data_errors
	result := lib.result_helper_with_severity(rego.metadata.chain(), [e.message], e.severity)
}
```

