#     expected format.
#   collections:
#   - redhat
#   - policy_data
#   - redhat_rpms
deny contains result if {
	some error in lib.sbom.rule_data_errors
	result := lib.result_helper_with_severity(rego.metadata.chain(), [error.message], error.severity)
}
